export function periodKey(period, now = Date.now()) {
  const d = new Date(now);
  if (period === "month") return d.getUTCFullYear() + "-" + String(d.getUTCMonth() + 1).padStart(2, "0");
  if (period === "week") {
    const day = (d.getUTCDay() + 6) % 7; // Monday = 0
