          id: "r" + state.seq,
          tool: args.tool,
          agents: args.agent ? [args.agent] : void 0,
          workspaces: args.workspace ? [args.workspace] : void 0,
          action: args.policyAction,
          reason: args.reason ?? "",
          priority: args.priority ?? 0,
        };
