      const entries = readAudit(config.root);
      const summary = summarize(entries);
      return {
        action: "status",
        ok: true,
        message: "governance posture",
        data: {
          root: config.root,
          rules: state.rules.length,
          audit: summary,
          quotas: state.quotas,
        },
      };
    },
    presentCall: (args) => ({
      card: "generic",
      title: "gov " + String(args.action),
      kind: "other",
      rawInput: args,
